	CnvUtfConverter::ConvertFromUnicodeToUtf8(msgtext8, msg2);

	TBuf<80> command1;
	command1.Format(_L("Restroom_TV_On"));

	TBuf<80> command2;
	command2.Format(_L("Restroom_TV_Off"));

	TBuf<80> command3;
	command3.Format(_L("Restroom_Stereo_On"));

	TBuf<80> command4;
	command4.Format(_L("Restroom_Stereo_Off"));

	TBuf<80> command5;
	command5.Format(_L("Restroom_Light_On"));

	TBuf<80> command6;
	command6.Format(_L("Restroom_Light_Off"));

	TBuf<80> command7;
	command7.Format(_L("Restroom_Computer_On"));

